#include "mfrk/ui_scene_prefix.hpp"
#include "ui_scene_fixture_decode.hpp"
#include <iostream>
using namespace mfrk::ui::scene;using namespace mfrk::ui::scene::test;
struct Case{Attributes local,style;Constants numbers,after;StringConstants strings;DeclaredGeometryInput input;std::array<int,2>physical;float view;int direction;bool strict,check,has_geometry=true,has_item=true;std::array<double,4>raw;int mode;FlexProperties properties;BoundsFailure failure;std::array<int,4>bounds{};Geometry geometry;std::array<std::uint32_t,15>scalar{};};
bool same(double a,double b){return std::bit_cast<std::uint64_t>(a)==std::bit_cast<std::uint64_t>(b);}
bool same_numbers(const Constants&a,const Constants&b){if(a.size()!=b.size())return false;for(const auto&[key,value]:a){auto found=b.find(key);if(found==b.end()||!same(value,found->second))return false;}return true;}
std::array<std::uint32_t,15> encode(const mfrk::ui::flex::Item&i){auto f=[](float x){return std::bit_cast<std::uint32_t>(x);};return{std::bit_cast<std::uint32_t>(std::int32_t(i.order)),f(i.grow),f(i.shrink),f(i.basis),std::bit_cast<std::uint32_t>(std::int32_t(i.align)),f(i.size[0]),f(i.minimum[0]),f(i.maximum[0]),f(i.size[1]),f(i.minimum[1]),f(i.maximum[1]),f(i.margin[0][0]),f(i.margin[0][1]),f(i.margin[1][0]),f(i.margin[1][1])};}
int main(int argc,char**argv)try{if(argc!=2&&argc!=3)throw std::runtime_error("fixture required");const bool parent_kinds=argc==3;auto&id=identity(parent_kinds?argv[1]:"geometry");auto r=Reader::file(argv[argc-1],id);std::vector<Case>cases;
for(unsigned k=0;k<id.count;++k){Case c;if(parent_kinds){auto parent=r.u32();if(parent>3)throw std::runtime_error("parent kind");c.input.parent_kind=DeclaredParent(parent);}c.local=attrs(r);c.style=attrs(r);c.numbers=numbers(r);c.strings=strings(r);for(auto&v:c.input.parent_dimensions)v=r.i32();for(auto&v:c.input.intrinsic)v=r.i32();if(r.flag()){std::array<int,4>previous;for(auto&v:previous)v=r.i32();c.input.previous=previous;}for(auto&v:c.physical)v=r.i32();c.view=r.f32();c.direction=r.i32();c.strict=r.flag();c.input.context_check_bounds=r.flag();c.input.initial_check_bounds=r.flag();c.check=r.flag();c.input.initial_mode=r.i32();for(auto&v:c.raw)v=r.f64();c.mode=r.i32();for(auto&v:c.properties.values)v=r.i32();c.properties.force_scale=r.flag();auto failure=r.u32();if(failure>4)throw std::runtime_error("failure code");c.failure=BoundsFailure(failure);c.after=numbers(r);if(c.failure==BoundsFailure::none){for(auto&v:c.bounds)v=r.i32();if(parent_kinds)c.has_geometry=r.flag();if(c.has_geometry){for(auto&v:c.geometry.relative)v=r.f64();for(auto&v:c.geometry.absolute)v=r.f64();}if(parent_kinds)c.has_item=r.flag();if(c.has_item)for(auto&v:c.scalar)v=r.u32();}cases.push_back(std::move(c));}r.end();unsigned bad=0,accepted=0,rejected=0,specs=0,items=0;
for(const auto&c:cases){bool different=false;try{auto values=c.numbers;StyleRegistry registry;if(!c.style.empty())registry.emplace("TestStyle",c.style);GeometryPipelineInput input;input.declaration=c.input;input.physical_parent=c.physical;input.direction=c.direction;input.view_scale=c.view;auto joined=compile_geometry_pipeline(c.local,registry,values,input,c.strings,c.strict);auto&result=joined.declaration;different=result.mode!=c.mode||result.check_bounds!=c.check||result.properties.values!=c.properties.values||result.properties.force_scale!=c.properties.force_scale||result.failure!=c.failure||!same_numbers(values,c.after);for(unsigned j=0;j<4;++j)different|=!same(result.raw[j],c.raw[j]);if(c.failure==BoundsFailure::none){++accepted;different|=!result.bounds||*result.bounds!=c.bounds;different|=joined.spec.has_value()!=c.has_geometry||joined.item.has_value()!=c.has_item;if(joined.spec&&c.has_geometry){++specs;for(unsigned j=0;j<4;++j)different|=!same(joined.spec->relative[j],c.geometry.relative[j])||!same(joined.spec->absolute[j],c.geometry.absolute[j]);}if(joined.item&&c.has_item){++items;different|=encode(*joined.item)!=c.scalar;}}else{++rejected;different|=result.bounds.has_value();}}catch(const std::exception&e){different=true;if(bad<8)std::cerr<<"exception "<<e.what()<<'\n';}if(different){if(bad<8)std::cerr<<"case "<<(&c-cases.data())<<" mismatch\n";++bad;}}
std::cout<<cases.size()<<" original joined prefixes, "<<accepted<<" accepted, "<<specs<<" specs, "<<items<<" items, "<<rejected<<" bounds rejections, "<<bad<<" mismatches\n";return bad?1:0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}
